import sys
p = sys.argv[1] if len(sys.argv) > 1 else '/opt/radar/radar.py'
s = open(p, encoding='utf-8').read()

old_json = '''Оцени сообщение и ответь строго JSON без пояснений:
{"relevant": true|false, "score": 1-5, "topic": "счёт|ВНЖ|компания|ВЭД|другое", "said": "суть сообщения одной фразой", "meaning": "что это значит для нас: какая у человека задача и чем мы можем помочь, 1–2 фразы", "reply": "черновик ответа или пустая строка"}
score: 5 — прямой запрос помощи по целевой теме (отказ банка, нужен счёт компании, ВНЖ, компания, платёжный агент для Китая); 4 — конкретный вопрос по целевой теме; 3 — обсуждение по целевой теме, где можно дать дельный совет; 1–2 — не отвечать.'''
new_json = '''НАШ КЛИЕНТ (главный фильтр): люди с деньгами и бизнесом. Собственники и директора компаний, предприниматели с международным бизнесом, компании в нескольких странах, ВЭД, импорт и экспорт с серьёзными объёмами, платёжные агенты и те, кто строит расчёты с контрагентами, НДС/VAT, холдинги, инвесторы, трейдеры и крипто-проекты с оборотами, люди, которые переезжают с семьёй и капиталом, хотят нормальный банк, кредитку, ипотеку, золотую визу. Признаки: «моя компания», «наши контрагенты», «оборот», «поставки», «инвойсы», «юрлицо», «несколько стран», «холдинг», «зарплатный проект», крупные суммы (от десятков тысяч долларов), премиальные банки (Emirates NBD, Mashreq, ADCB, FAB, private banking).
НЕ НАШ КЛИЕНТ (score 1–2, даже если тема формально про счёт или карту): мелкие личные задачи на небольшие деньги. Например, оформить армянскую, киргизскую, казахскую или другую зарубежную карту за 15–30 тысяч рублей, пополнить китайскую карту или UnionPay на 10 тысяч, оплатить подписку или отель за границей, «где дешевле карта», студенты и туристы, поиск самого дешёвого способа. Такие люди не купят услугу за тысячи долларов.
Если по сообщению непонятно, бизнес это или мелкая личная задача, смотри на контекст чата и формулировки; при сомнениях ставь не выше 3.

Оцени сообщение и ответь строго JSON без пояснений:
{"relevant": true|false, "score": 1-5, "tier": "бизнес|состоятельный частный|мелкий|непонятно", "topic": "счёт|ВНЖ|компания|ВЭД|другое", "said": "суть сообщения одной фразой", "meaning": "что это значит для нас: кто человек (бизнес или частник, примерный масштаб), какая у него задача и чем мы можем помочь, 1–2 фразы", "reply": "черновик ответа или пустая строка"}
score: 5 — бизнес или состоятельный человек с прямым запросом по целевой теме (отказ банка компании, нужен корпоративный счёт, ВНЖ с переездом, компания в ОАЭ, платёжный агент или расчёты с Китаем на объёмах); 4 — конкретный вопрос по целевой теме от бизнеса или состоятельного человека; 3 — обсуждение по целевой теме, где виден бизнес-контекст и можно дать дельный совет; 1–2 — мелкие личные задачи, нецелевые темы, не отвечать.'''
if '"tier"' not in s:
    assert old_json in s, 'prompt anchor'
    s = s.replace(old_json, new_json, 1)

old_card = '''        msg = (f"<b>🎯 Лид #{lid} · {e(res.get('score'))}/5 · {e(res.get('topic',''))}</b>\\n"'''
new_card = '''        msg = (f"<b>🎯 Лид #{lid} · {e(res.get('score'))}/5 · {e(res.get('topic',''))} · {e(res.get('tier',''))}</b>\\n"'''
if "res.get('tier'" not in s:
    assert old_card in s, 'card anchor'
    s = s.replace(old_card, new_card, 1)

# реакции только на бизнес и состоятельных
old_r = '''        asyncio.get_event_loop().create_task(reactions.maybe_react(user, ev.chat_id, ev.id, sender.id, text))'''
new_r = '''        if res.get("tier") in ("бизнес", "состоятельный частный") and int(res.get("score", 0)) >= 3:
            asyncio.get_event_loop().create_task(reactions.maybe_react(user, ev.chat_id, ev.id, sender.id, text))'''
if old_r in s and 'res.get("tier") in' not in s:
    s = s.replace(old_r, new_r, 1)

# ключевые слова бизнеса в фильтр до нейросети
if 'холдинг|контрагент' not in s:
    s = s.replace('STRONG_RE = re.compile(r"', 'STRONG_RE = re.compile(r"\\bндс\\b|\\bvat\\b|холдинг|контрагент|оборот\\w* компан|наша компани|моя компани|зарплатн\\w* проект|private banking|золот\\w* виз|', 1)
open(p, 'w', encoding='utf-8').write(s)
print('OK9')
